class MyLinkedList {private static class Link{int value;Link next;Link(int v,Link n){value=v;next=n;}}Link head=new Link(0,null);int size=0;public MyLinkedList(){}public int get(int index){if(index<0||index>=size)return -1;Link n=head.next;while(index-->0)n=n.next;return n.value;}public void addAtHead(int val){addAtIndex(0,val);}public void addAtTail(int val){addAtIndex(size,val);}public void addAtIndex(int index,int val){if(index>size)return;Link n=head;for(int i=0;i<index;i++)n=n.next;n.next=new Link(val,n.next);size++;}public void deleteAtIndex(int index){if(index<0||index>=size)return;Link n=head;while(index-->0)n=n.next;n.next=n.next.next;size--;}}
